<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Conway's Game of Life</title>
<style>
  * { box-sizing: border-box; }
  html, body { margin: 0; padding: 0; }
  body {
    min-height: 100vh;
    background: radial-gradient(ellipse at top, #131c33 0%, #050811 70%);
    color: #d8e0f0;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", system-ui, "Helvetica Neue", Arial, sans-serif;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 24px;
  }
  .app { text-align: center; }
  h1 {
    margin: 0 0 20px;
    font-size: 26px;
    font-weight: 600;
    letter-spacing: 0.6px;
    color: #7cffb2;
    text-shadow: 0 0 24px rgba(124, 255, 178, 0.35);
  }
  .wrap {
    display: inline-block;
    padding: 14px;
    background: linear-gradient(135deg, #1a2540 0%, #0c1120 100%);
    border: 1px solid rgba(124, 255, 178, 0.15);
    border-radius: 14px;
    box-shadow:
      0 20px 60px rgba(0, 0, 0, 0.6),
      0 0 40px rgba(124, 255, 178, 0.08),
      inset 0 1px 0 rgba(255, 255, 255, 0.05);
  }
  canvas {
    display: block;
    background: #050811;
    border-radius: 8px;
    cursor: crosshair;
    user-select: none;
    -webkit-user-select: none;
    touch-action: none;
  }
  .controls {
    margin-top: 18px;
    display: flex;
    gap: 10px;
    justify-content: center;
    flex-wrap: wrap;
  }
  button {
    background: #162038;
    color: #d8e0f0;
    border: 1px solid #2a3a5e;
    padding: 10px 18px;
    font-size: 14px;
    font-weight: 500;
    border-radius: 8px;
    cursor: pointer;
    transition: all 0.15s ease;
    font-family: inherit;
    letter-spacing: 0.3px;
  }
  button:hover {
    background: #1f2c4d;
    border-color: rgba(124, 255, 178, 0.6);
    color: #fff;
    transform: translateY(-1px);
  }
  button:active { transform: translateY(0); }
  button.playing {
    background: #7cffb2;
    color: #050811;
    border-color: #7cffb2;
    box-shadow: 0 0 18px rgba(124, 255, 178, 0.5);
  }
  button.playing:hover {
    background: #95ffc4;
    color: #050811;
  }
  .stats {
    margin-top: 16px;
    font-size: 13px;
    color: #6b7a99;
    font-variant-numeric: tabular-nums;
    letter-spacing: 0.3px;
  }
  .stats b {
    color: #7cffb2;
    font-weight: 600;
    margin: 0 4px;
  }
</style>
</head>
<body>
  <div class="app">
    <h1>Conway's Game of Life</h1>
    <div class="wrap">
      <canvas id="life" width="500" height="500"></canvas>
    </div>
    <div class="controls">
      <button id="step">Step ▸</button>
      <button id="play">Play ▶</button>
      <button id="random">Random</button>
      <button id="clear">Clear</button>
    </div>
    <div class="stats">Generation<b id="gen">0</b>· Population<b id="pop">0</b></div>
  </div>
  <script>
  (function() {
    'use strict';

    const canvas = document.getElementById('life');
    const ctx = canvas.getContext('2d');
    const stepBtn = document.getElementById('step');
    const playBtn = document.getElementById('play');
    const randomBtn = document.getElementById('random');
    const clearBtn = document.getElementById('clear');
    const genEl = document.getElementById('gen');
    const popEl = document.getElementById('pop');

    const W = 50;
    const H = 50;
    const CSS_SIZE = 500;
    const CELL = CSS_SIZE / W; // 10 px per cell

    // High-DPI handling
    const DPR = window.devicePixelRatio || 1;
    canvas.width = CSS_SIZE * DPR;
    canvas.height = CSS_SIZE * DPR;
    canvas.style.width = CSS_SIZE + 'px';
    canvas.style.height = CSS_SIZE + 'px';
    ctx.scale(DPR, DPR);

    let grid = new Uint8Array(W * H);
    let next = new Uint8Array(W * H);
    let generation = 0;
    let playing = false;
    let timer = null;
    let paintValue = 1;
    let painting = false;

    function idx(x, y) { return y * W + x; }

    function draw() {
      // Background
      ctx.fillStyle = '#050811';
      ctx.fillRect(0, 0, CSS_SIZE, CSS_SIZE);

      // Live cells
      ctx.fillStyle = '#7cffb2';
      for (let y = 0; y < H; y++) {
        for (let x = 0; x < W; x++) {
          if (grid[idx(x, y)]) {
            ctx.fillRect(x * CELL + 0.5, y * CELL + 0.5, CELL - 1, CELL - 1);
          }
        }
      }

      // Subtle grid lines
      ctx.strokeStyle = 'rgba(124, 255, 178, 0.05)';
      ctx.lineWidth = 1;
      ctx.beginPath();
      for (let i = 0; i <= W; i++) {
        ctx.moveTo(i * CELL + 0.5, 0);
        ctx.lineTo(i * CELL + 0.5, CSS_SIZE);
      }
      for (let i = 0; i <= H; i++) {
        ctx.moveTo(0, i * CELL + 0.5);
        ctx.lineTo(CSS_SIZE, i * CELL + 0.5);
      }
      ctx.stroke();

      // Stats
      let pop = 0;
      for (let i = 0; i < grid.length; i++) pop += grid[i];
      popEl.textContent = pop;
      genEl.textContent = generation;
    }

    function step() {
      // Compute the next generation simultaneously from the current grid.
      // Edges count as dead (out-of-bounds cells are skipped, contributing 0).
      for (let y = 0; y < H; y++) {
        for (let x = 0; x < W; x++) {
          let n = 0;
          for (let dy = -1; dy <= 1; dy++) {
            const ny = y + dy;
            if (ny < 0 || ny >= H) continue;
            for (let dx = -1; dx <= 1; dx++) {
              if (dx === 0 && dy === 0) continue;
              const nx = x + dx;
              if (nx < 0 || nx >= W) continue;
              n += grid[idx(nx, ny)];
            }
          }
          const alive = grid[idx(x, y)];
          if (alive) {
            // Survives on 2 or 3 neighbours
            next[idx(x, y)] = (n === 2 || n === 3) ? 1 : 0;
          } else {
            // Born on exactly 3 neighbours
            next[idx(x, y)] = (n === 3) ? 1 : 0;
          }
        }
      }
      // Swap buffers so every cell sees the same starting state
      const tmp = grid;
      grid = next;
      next = tmp;
      generation++;
      draw();
    }

    function clear() {
      grid.fill(0);
      generation = 0;
      draw();
    }

    function randomize() {
      for (let i = 0; i < grid.length; i++) {
        grid[i] = Math.random() < 0.28 ? 1 : 0;
      }
      generation = 0;
      draw();
    }

    function togglePlay() {
      playing = !playing;
      playBtn.textContent = playing ? 'Pause ❚❚' : 'Play ▶';
      playBtn.classList.toggle('playing', playing);
      if (playing) {
        timer = setInterval(step, 100);
      } else {
        if (timer !== null) clearInterval(timer);
        timer = null;
      }
    }

    function eventToCell(e) {
      const rect = canvas.getBoundingClientRect();
      let cx, cy;
      if (e.touches && e.touches.length) {
        cx = e.touches[0].clientX;
        cy = e.touches[0].clientY;
      } else {
        cx = e.clientX;
        cy = e.clientY;
      }
      return { x: Math.floor((cx - rect.left) / CELL), y: Math.floor((cy - rect.top) / CELL) };
    }

    function paintAt(x, y) {
      if (x < 0 || x >= W || y < 0 || y >= H) return;
      grid[idx(x, y)] = paintValue;
      draw();
    }

    // Mouse events
    canvas.addEventListener('mousedown', (e) => {
      e.preventDefault();
      const { x, y } = eventToCell(e);
      if (x < 0 || x >= W || y < 0 || y >= H) return;
      // Toggle behaviour: clicking an alive cell starts a "paint dead" stroke,
      // clicking a dead cell starts a "paint alive" stroke.
      paintValue = grid[idx(x, y)] ? 0 : 1;
      painting = true;
      paintAt(x, y);
    });
    canvas.addEventListener('mousemove', (e) => {
      if (!painting) return;
      const { x, y } = eventToCell(e);
      paintAt(x, y);
    });
    document.addEventListener('mouseup', () => { painting = false; });
    canvas.addEventListener('mouseleave', () => { painting = false; });

    // Touch events
    canvas.addEventListener('touchstart', (e) => {
      e.preventDefault();
      const { x, y } = eventToCell(e);
      if (x < 0 || x >= W || y < 0 || y >= H) return;
      paintValue = grid[idx(x, y)] ? 0 : 1;
      painting = true;
      paintAt(x, y);
    }, { passive: false });
    canvas.addEventListener('touchmove', (e) => {
      e.preventDefault();
      if (!painting) return;
      const { x, y } = eventToCell(e);
      paintAt(x, y);
    }, { passive: false });
    canvas.addEventListener('touchend', () => { painting = false; });
    canvas.addEventListener('touchcancel', () => { painting = false; });

    // Buttons
    stepBtn.addEventListener('click', () => { step(); });
    playBtn.addEventListener('click', togglePlay);
    randomBtn.addEventListener('click', randomize);
    clearBtn.addEventListener('click', () => {
      if (playing) togglePlay();
      clear();
    });

    // Public API used by the grader
    window.life = {
      w: W,
      h: H,
      get(x, y) {
        if (x < 0 || x >= W || y < 0 || y >= H) return 0;
        return grid[idx(x, y)];
      },
      set(x, y, v) {
        if (x < 0 || x >= W || y < 0 || y >= H) return;
        grid[idx(x, y)] = v ? 1 : 0;
        draw();
      },
      step,
      clear,
    };

    draw();
  })();
  </script>
</body>
</html>
